const Redis = require('ioredis');
const redis = new Redis({ host: 'redis', port: 6379, db: 0 });

try {
    const body = $input.first().json.body || $input.first().json;
    const headers = $input.first().json.headers || {};

    const ip = headers['x-forwarded-for']?.split(',')[0]?.trim()
        || headers['x-real-ip']
        || 'unknown';

    const fp = headers['x-fingerprint']
        || body.fingerprint
        || ('sse_' + ip.replace(/[^a-z0-9]/gi, '_'));

    const view = body.view || 'standard';
    const query = body.query || {};

    // Derive intent label matching the feed workflow logic
    const v = String(view).toLowerCase();
    let intent = 'SSE Feed';
    if (v === 'map_3d')   intent = 'Tactical 3D';
    else if (v === 'map_2d')   intent = 'Tactical 2D';
    else if (v === 'map_flat') intent = 'Flat Map';
    else if (v === 'mosaic')   intent = 'Mosaic Grid';
    else if (v === 'compact')  intent = 'Compact Feed';
    else if (v === 'standard') intent = 'SSE Feed';
    if (query.w_space) intent = 'W-Space Hunter';

    // Geo lookup from cache (populated by existing geo worker)
    let geo = null;
    if (ip && ip !== 'unknown') {
        const cached = await redis.get('intel:geo:' + ip);
        if (cached && cached !== 'null') {
            try { geo = JSON.parse(cached); } catch(e) {}
        }
    }

    const logEntry = JSON.stringify({
        id: fp,
        ip,
        geo,
        ua: headers['user-agent'] || null,
        ts: Math.floor(Date.now() / 1000),
        intent,
        view,
        query,
        sse: true,
        perf: { ms: 0, scanned: 0, returned: 0 }
    });

    const pipe = redis.pipeline();
    pipe.lpush('intel:logs:connections', logEntry);
    pipe.ltrim('intel:logs:connections', 0, 49999);

    // Keep the pilot marked active (same 15-min TTL as feed workflow)
    pipe.zadd('intel:active:pilots', Math.floor(Date.now() / 1000), fp);

    // Track session start time (only set on first ping — NX prevents overwrite on reconnect)
    pipe.set('intel:session:start:' + fp, Math.floor(Date.now() / 1000), 'EX', 86400, 'NX');

    // Increment SSE-specific view counter
    pipe.hincrby('intel:usage:stats', 'sse_' + v, 1);

    await pipe.exec();

    return [{ json: { ok: true } }];
} catch (e) {
    return [{ json: { ok: false, error: e.message } }];
} finally {
    redis.quit();
}
